package de.backendlab.experiments;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.*;import java.net.*;import java.net.http.*;
/** Portable experiment kernels. Executors are owned by callers, not this class. */
public final class Experiments {
 private Experiments(){}
 public static Map<String,Object> reserve(String mode,int stock,int requests,Executor executor) {
  if(stock<0||requests<1||requests>2000)throw new IllegalArgumentException("stock >= 0, requests 1..2000");
  AtomicInteger remaining=new AtomicInteger(stock), accepted=new AtomicInteger(); Object lock=new Object(); int[] unsafe={stock};
  Runnable task=()->{boolean ok; switch(mode){case "unsafe": int n=unsafe[0];Thread.yield();ok=n>0;if(ok)unsafe[0]=n-1;break;case "lock": synchronized(lock){ok=remaining.get()>0;if(ok)remaining.decrementAndGet();}break;case "atomic": int old;do{old=remaining.get();if(old<=0)break;}while(!remaining.compareAndSet(old,old-1));ok=old>0;break;default:throw new IllegalArgumentException("mode");}if(ok)accepted.incrementAndGet();};
  var jobs=new ArrayList<CompletableFuture<Void>>();for(int i=0;i<requests;i++)jobs.add(CompletableFuture.runAsync(task,executor));CompletableFuture.allOf(jobs.toArray(CompletableFuture[]::new)).join();
  int left=mode.equals("unsafe")?unsafe[0]:remaining.get();return Map.of("accepted",accepted.get(),"remaining",left,"correct",accepted.get()==Math.min(stock,requests)&&left==Math.max(0,stock-requests));
 }
 public static long work(int i,int rounds){long x=i+1;for(int j=0;j<rounds;j++){x^=x<<13;x^=x>>>7;x^=x<<17;}return x;}
 public static Map<String,Object> cpu(int count,int rounds,int workers,Executor executor){if(count<1||count>100000||rounds<1||rounds>1000||workers<1||workers>32)throw new IllegalArgumentException("bounds");long start=System.nanoTime(),sum=0; if(workers==1){for(int i=0;i<count;i++)sum+=work(i,rounds);}else{var jobs=new ArrayList<CompletableFuture<Long>>();for(int k=0;k<workers;k++){final int a=k; jobs.add(CompletableFuture.supplyAsync(()->{long s=0;for(int i=a;i<count;i+=workers)s+=work(i,rounds);return s;},executor));}for(var j:jobs)sum+=j.join();}return Map.of("checksum",Long.toString(sum),"elapsedNs",System.nanoTime()-start,"processors",Runtime.getRuntime().availableProcessors());}
 public static CompletionStage<List<String>> io(HttpClient client,String url,String mode,Executor executor){var paths=List.of("product","inventory","pricing");Function<String,HttpRequest> req=p->HttpRequest.newBuilder(URI.create(url+"/"+p)).timeout(java.time.Duration.ofSeconds(5)).build();Function<HttpResponse<String>,String> body=x->{if(x.statusCode()!=200)throw new IllegalStateException("upstream "+x.statusCode());return x.body();};
 if(mode.equals("blocking")){var result=new ArrayList<String>();for(String p:paths)try{result.add(body.apply(client.send(req.apply(p),HttpResponse.BodyHandlers.ofString())));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new CompletionException(e);}catch(java.io.IOException e){throw new CompletionException(e);}return CompletableFuture.completedFuture(result);}
 if(mode.equals("sequential-async")){CompletableFuture<List<String>> f=CompletableFuture.completedFuture(new ArrayList<>());for(String p:paths)f=f.thenCompose(list->client.sendAsync(req.apply(p),HttpResponse.BodyHandlers.ofString()).thenApply(x->{list.add(body.apply(x));return list;}));return f;}
 if(!mode.equals("concurrent"))throw new IllegalArgumentException("mode");var jobs=paths.stream().map(p->client.sendAsync(req.apply(p),HttpResponse.BodyHandlers.ofString()).thenApply(body)).toList();return CompletableFuture.allOf(jobs.toArray(CompletableFuture[]::new)).thenApply(v->jobs.stream().map(CompletableFuture::join).toList());}
 public static Map<String,Object> stampede(int requests,boolean single,Executor executor){if(requests<1||requests>100)throw new IllegalArgumentException("requests 1..100");AtomicInteger loads=new AtomicInteger();Object lock=new Object();AtomicReference<String> cache=new AtomicReference<>();var jobs=new ArrayList<CompletableFuture<Void>>();Runnable load=()->{loads.incrementAndGet();try{Thread.sleep(20);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new CompletionException(e);}cache.set("product");};for(int i=0;i<requests;i++)jobs.add(CompletableFuture.runAsync(()->{if(cache.get()==null){if(single){synchronized(lock){if(cache.get()==null)load.run();}}else load.run();}},executor));CompletableFuture.allOf(jobs.toArray(CompletableFuture[]::new)).join();return Map.of("loads",loads.get(),"requests",requests);}
 public static Map<String,Object> pool(int requests,int permits,Executor executor){if(requests<1||requests>100||permits<1||permits>50)throw new IllegalArgumentException("bounds");Semaphore gate=new Semaphore(permits);AtomicInteger active=new AtomicInteger(),peak=new AtomicInteger(),rejected=new AtomicInteger();var jobs=new ArrayList<CompletableFuture<Void>>();for(int i=0;i<requests;i++)jobs.add(CompletableFuture.runAsync(()->{try{if(!gate.tryAcquire(100,TimeUnit.MILLISECONDS)){rejected.incrementAndGet();return;}try{peak.accumulateAndGet(active.incrementAndGet(),Math::max);Thread.sleep(30);}finally{active.decrementAndGet();gate.release();}}catch(InterruptedException e){Thread.currentThread().interrupt();throw new CompletionException(e);}},executor));CompletableFuture.allOf(jobs.toArray(CompletableFuture[]::new)).join();return Map.of("peak",peak.get(),"rejected",rejected.get(),"permits",permits);}
}
